cypress_script:
describe('Select Menu Functionality', () => {
  it('should allow the user to select a color', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#oldSelectMenu').select('Red');
    cy.url().should('eq', 'https://demoqa.com/select-menu');
  });
  it('should not change the URL when no color is selected', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#oldSelectMenu').select('');
    cy.url().should('eq', 'https://demoqa.com/select-menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Select Menu Functionality', () => {
  test('should allow the user to select a color', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#oldSelectMenu', 'Red');
    expect(page.url()).toBe('https://demoqa.com/select-menu');
  });
  test('should not change the URL when no color is selected', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#oldSelectMenu', '');
    expect(page.url()).toBe('https://demoqa.com/select-menu');
  });
});
